// Generates the API contract used by the SPA from the backend:
//   1. the OpenAPI document (src/api/openapi.json), exported by `erable openapi`;
//   2. the TypeScript types (src/api/schema.ts), generated by openapi-typescript.
//
// Usage:
//   node scripts/api-generate.mjs           regenerate both files
//   node scripts/api-generate.mjs --check   fail if either versioned file is out of date (CI)
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { pathToFileURL } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";
import { format, resolveConfig } from "prettier";
import ts from "typescript";

const webDir = resolve(import.meta.dirname, "..");
const repoDir = resolve(webDir, "..", "..");
const documentPath = join(webDir, "src", "api", "openapi.json");
const schemaPath = join(webDir, "src", "api", "schema.ts");
const check = process.argv.includes("--check");

const header = `/**
 * Generated by scripts/api-generate.mjs from openapi.json. Do not edit.
 * Regenerate with \`pnpm -C src/web api:generate\`.
 */

`;
const elementIdImport = `import type { ElementId } from "../shared/ids/elementId";

`;

// OpenAPI format published by the backend for element IDs (ErableHost.ElementIdSchemaFormat): every such field
// gets the branded type, obtainable only through parseElementId() (docs/architecture.md §4).
const elementIdFormat = "element-id";
const elementIdType = ts.factory.createTypeReferenceNode("ElementId");

function exportDocument(target) {
  execFileSync(
    "dotnet",
    [
      "run",
      "--project",
      join(repoDir, "src", "Erable.Server"),
      "--no-launch-profile",
      "--",
      "openapi",
      "--output",
      target,
    ],
    { stdio: ["ignore", "ignore", "inherit"] },
  );
  return readFileSync(target, "utf8");
}

async function generateSchema(documentFile) {
  const ast = await openapiTS(pathToFileURL(documentFile), {
    alphabetize: true,
    transform: (schema) => (schema.format === elementIdFormat ? elementIdType : undefined),
  });
  const prettierConfig = (await resolveConfig(schemaPath)) ?? {};
  const body = astToString(ast);
  // Imported only when used: an unused import would fail `noUnusedLocals`.
  const imports = /\bElementId\b/.test(body) ? elementIdImport : "";
  return format(header + imports + body, { ...prettierConfig, parser: "typescript" });
}

const readOrEmpty = (path) => {
  try {
    return readFileSync(path, "utf8");
  } catch {
    return "";
  }
};

if (check) {
  const tmp = mkdtempSync(join(tmpdir(), "erable-api-"));
  try {
    const liveDocument = exportDocument(join(tmp, "openapi.json"));
    const liveSchema = await generateSchema(join(tmp, "openapi.json"));
    const stale = [];
    if (liveDocument !== readOrEmpty(documentPath)) stale.push(documentPath);
    if (liveSchema !== readOrEmpty(schemaPath)) stale.push(schemaPath);
    if (stale.length > 0) {
      console.error(`API contract out of date:\n  ${stale.join("\n  ")}`);
      console.error("Run `pnpm -C src/web api:generate` and commit the result.");
      process.exit(1);
    }
    console.log("API contract up to date.");
  } finally {
    rmSync(tmp, { recursive: true, force: true });
  }
} else {
  exportDocument(documentPath);
  writeFileSync(schemaPath, await generateSchema(documentPath));
  console.log(`Wrote ${documentPath}\nWrote ${schemaPath}`);
}
